"""SHA-guarded S2 Task 6/7 HTTP candidate. CI formats and emits blobs; it never moves a ref."""
from pathlib import Path
import base64,gzip,hashlib,subprocess
EXPECTED={
    "apps/aiks-service/src/team/auth_routes.rs": "c66ef64d6ab24d1dfbaf8dcbeafe5d0757110ea9",
    "apps/aiks-service/src/team/mod.rs": "ad6a8cb7ea1191ee929c3787f85e8e5ea674ee49",
    "apps/aiks-service/src/team/business_routes.rs": None,
    "apps/aiks-service/src/team/middleware.rs": None,
    "apps/aiks-service/src/team/share_routes.rs": None,
    "apps/aiks-service/tests/team_isolation.rs": None,
    "apps/aiks-service/tests/team_sharing.rs": None,
    "apps/aiks-service/tests/team_support/mod.rs": None,
}
PATCH_SHA256="fb66e01e337b0298c597fb716241127a4b3d59a16a9d4e83f3d124aa10763eef"
PATCH_B64=""
for path, expected in EXPECTED.items():
    p=Path(path)
    if expected is None:
        assert not p.exists(), (path, "unexpected-existing-file")
    else:
        actual=subprocess.check_output(["git","hash-object",path],text=True).strip()
        assert actual==expected,(path,actual,expected)
patch=gzip.decompress(base64.b64decode(PATCH_B64))
assert hashlib.sha256(patch).hexdigest()==PATCH_SHA256
subprocess.run(["git","apply","--whitespace=nowarn","-"],input=patch,check=True)
new_files=[path for path, expected in EXPECTED.items() if expected is None]
subprocess.run(["git","add","-N",*new_files],check=True)
print("Applied SHA-guarded Task 6/7 HTTP candidate; branch still requires explicit reviewed commit.")
